test('central resume control selects the next safe stage and honors terminal and limit states',()=>{const pipeline=['planner','developer','tester','reviewer'] as const;assert.deepEqual(getResumeControl({pipeline:[...pipeline],status:'needs_manual_review',workspaceTokenLimitExceeded:{tokenUsage:100},environmentStatus:'manual_review_preserved',workspaceLimitActive:false}),{canResume:true,resumeFromStage:'planner',blockedReason:null});assert.equal(getResumeControl({pipeline:[...pipeline],lastSuccessfulStage:'planner',status:'needs_manual_review',workspaceTokenLimitExceeded:{tokenUsage:100},environmentStatus:'manual_review_preserved',workspaceLimitActive:false}).resumeFromStage,'developer');assert.equal(getResumeControl({pipeline:[...pipeline],lastSuccessfulStage:'developer',status:'needs_manual_review',workspaceTokenLimitExceeded:{tokenUsage:100},environmentStatus:'manual_review_preserved',workspaceLimitActive:false}).resumeFromStage,'tester');assert.equal(getResumeControl({pipeline:[...pipeline],lastSuccessfulStage:'tester',status:'needs_manual_review',workspaceTokenLimitExceeded:{tokenUsage:100},environmentStatus:'manual_review_preserved',workspaceLimitActive:false}).resumeFromStage,'reviewer');const budget=getResumeControl({pipeline:[...pipeline],lastSuccessfulStage:'planner',status:'needs_manual_review',budgetExceeded:{tokenUsage:101},tokenUsage:101,tokenBudget:100});assert.equal(budget.canResume,false);assert.equal(budget.blockedReason,'Limite de tokens da task ainda precisa ser aumentado para permitir a retomada.');const workspace=getResumeControl({pipeline:[...pipeline],lastSuccessfulStage:'planner',status:'needs_manual_review',workspaceTokenLimitExceeded:{tokenUsage:100},environmentStatus:'manual_review_preserved',workspaceLimitActive:true});assert.equal(workspace.canResume,false);assert.equal(workspace.blockedReason,'Retomada disponível após liberar o limite do workspace.');for(const status of ['approved','applied','discarded'])assert.deepEqual(getResumeControl({pipeline:[...pipeline],lastSuccessfulStage:'planner',status}),{canResume:false,resumeFromStage:null,blockedReason:null});});
test('resume distinguishes technical tester failure from functional tester failure',()=>{const pipeline=['planner','developer','tester','reviewer'] as const;const technical=getResumeControl({pipeline:[...pipeline],status:'failed',lastSuccessfulStage:'tester',currentStage:'tester',resumable:true,executions:[{role:'planner',status:'completed',startedAt:'2026-01-01T00:00:00Z'},{role:'developer',status:'completed',startedAt:'2026-01-01T00:01:00Z'},{role:'tester',status:'failed',startedAt:'2026-01-01T00:02:00Z'}]});assert.equal(technical.resumeFromStage,'tester');const functional=getResumeControl({pipeline:[...pipeline],status:'failed',lastSuccessfulStage:'tester',currentStage:'tester',resumable:true,executions:[{role:'planner',status:'completed',startedAt:'2026-01-01T00:00:00Z'},{role:'developer',status:'completed',startedAt:'2026-01-01T00:01:00Z'},{role:'tester',status:'completed',startedAt:'2026-01-01T00:02:00Z',structuredResult:{status:'FAILED'}}]});assert.equal(functional.resumeFromStage,'developer');assert.equal(functional.lastSafeStage,'developer');const blocked=getResumeControl({pipeline:[...pipeline],status:'failed',lastSuccessfulStage:'tester',currentStage:'tester',resumable:true,executions:[{role:'tester',status:'completed',startedAt:'2026-01-01T00:02:00Z',structuredResult:{status:'BLOCKED'}}]});assert.equal(blocked.resumeFromStage,'tester');const reviewer=getResumeControl({pipeline:[...pipeline],status:'failed',lastSuccessfulStage:'tester',currentStage:'reviewer',resumable:true,executions:[{role:'tester',status:'completed',startedAt:'2026-01-01T00:02:00Z',structuredResult:{status:'PASSED'}},{role:'reviewer',status:'failed',startedAt:'2026-01-01T00:03:00Z'}]});assert.equal(reviewer.resumeFromStage,'reviewer');const developer=getResumeControl({pipeline:[...pipeline],status:'failed',lastSuccessfulStage:'planner',currentStage:'developer',resumable:true,executions:[{role:'developer',status:'failed',startedAt:'2026-01-01T00:02:00Z'}]});assert.equal(developer.resumeFromStage,'developer');});
