import {EventEmitter} from 'node:events';
import {CodexCliAdapter,ReviewerProviderRouter,resolveExecutable} from '@orchestrator/adapters';

const codexContext:any={task:{id:'codex-test',title:'Review',description:'Review safely',pipeline:['reviewer'],status:'reviewing',resumable:true,workspaceId:'w',taskBudgetUsd:1,tokenBudget:1000,configSnapshot:'{}',createdAt:'',updatedAt:''},workspaceContext:{id:'w',type:'local',location:process.cwd(),branch:'main'},projectRules:[],stage:'reviewer',previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:1000,budgetUsd:1}};
function fakeSpawn(config:{stdout?:string;stderr?:string;code?:number|null;delay?:number;never?:boolean;onChildCreated?:(child:any)=>void;synchronousMetadata?:boolean}={}){return (_command:string,args:string[])=>{const child:any=new EventEmitter();child.stdout=new EventEmitter();child.stderr=new EventEmitter();const metadata=args.includes('--help')||args.includes('--version');child.stdin={end(){if(config.never&&!metadata)return;const finish=()=>{const output=args.includes('--help')?'Usage: codex exec [OPTIONS] [PROMPT]\n      --json\n      --sandbox <MODE>\n      --model <MODEL>':args.includes('--version')?(config.stdout||'codex-cli 0.160.0'):config.stdout;if(output)child.stdout.emit('data',Buffer.from(output));if(config.stderr)child.stderr.emit('data',Buffer.from(config.stderr));child.emit('close',metadata?0:(config.code??0));};if(metadata)finish();else setTimeout(finish,config.delay||0);}};child.kill=()=>{if(!child.closed){child.closed=true;child.emit('close',null);}};child.args=args;config.onChildCreated?.(child);return child;};}
function review(status:'APPROVED'|'NEEDS_FIX'='APPROVED'){return JSON.stringify({status,summary:'review summary',issues:status==='APPROVED'?[]:[{severity:'high',file:'src/app.ts',description:'Fix this issue'}]});}

test('codex reports CLI missing separately from authentication',async()=>{const adapter=new CodexCliAdapter({executable:'codex-not-installed-for-test'});assert.equal(await adapter.checkAvailability(),false);const health=await adapter.getHealth();assert.equal(health.available,false);assert.equal(health.authenticated,false);});
test('codex health captures version and authentication error',async()=>{const adapter=new CodexCliAdapter({executable:'codex',spawn:fakeSpawn({stdout:'codex 1.2.3',stderr:'authentication required',code:0})});assert.equal(await adapter.checkAvailability(),true);const health=await adapter.getHealth();assert.equal(health.version,'1.2.3');assert.equal(health.authenticated,false);assert.equal(health.authenticationStatus,'unknown');});
test('codex rejects non-zero exit and captures stderr',async()=>{const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stderr:'cli failure',code:2})});await assert.rejects(adapter.execute(codexContext),error=>{assert.equal((error as any).kind,'provider_error');assert.match(String(error),/cli failure/);return true;});});
test('codex validates APPROVED JSON and structured output',async()=>{let args:string[]=[];const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:(command,a)=>{args=a;return fakeSpawn({stdout:review('APPROVED')})(command,a);}});const result=await adapter.execute({...codexContext,onProgress(){},onHeartbeat(){}});assert.equal(result.structuredResult?.status,'APPROVED');assert.equal(result.stderr,'');assert.equal(result.tokenUsage,0);assert.ok(args.includes('--sandbox'));});
test('codex validates NEEDS_FIX JSON without textual approval fallback',async()=>{const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:review('NEEDS_FIX')})});const result=await adapter.execute(codexContext);assert.equal(result.structuredResult?.status,'NEEDS_FIX');assert.match(result.output,/NEEDS_FIX/);});
test('codex parses JSONL and uses the last valid agent_message',async()=>{const stream=[JSON.stringify({type:'thread.started',thread_id:'abc'}),'{not-json}',JSON.stringify({type:'item.completed',item:{type:'agent_message',text:'Analisando projeto...'}}),JSON.stringify({type:'item.completed',item:{type:'agent_message',text:review('APPROVED')}}),JSON.stringify({type:'turn.completed',usage:{input_tokens:100,output_tokens:20}})].join('\n');const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:stream})});const result=await adapter.execute(codexContext);assert.equal(result.structuredResult?.status,'APPROVED');assert.equal((result.rawProviderResponse as any).events.length,4);assert.equal((result.rawProviderResponse as any).turnCompleted,true);assert.equal(result.tokenUsage,120);});
test('codex parses NEEDS_FIX JSON inside a markdown code fence',async()=>{const text='```json\n'+review('NEEDS_FIX')+'\n```';const stream=JSON.stringify({type:'item.completed',item:{type:'agent_message',text}})+'\n'+JSON.stringify({type:'turn.completed'});const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:stream})});const result=await adapter.execute(codexContext);assert.equal(result.structuredResult?.status,'NEEDS_FIX');});
test('codex reports provider error when stream fails without completed turn',async()=>{const stream=JSON.stringify({type:'error',message:'provider failed'});const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:stream})});await assert.rejects(adapter.execute(codexContext),error=>{assert.equal((error as any).kind,'provider_error');return true;});});
test('codex rejects invalid JSON even when stdout contains APPROVED text',async()=>{const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:'APPROVED but not JSON'})});await assert.rejects(adapter.execute(codexContext),error=>{assert.equal((error as any).kind,'validation_error');return true;});});
