test('Claude Developer sends explicit acceptance IDs and dialog contract to stdin',async()=>{const prompts:string[]=[];const adapter=new ClaudeCodeAdapter({executable:'claude',model:'sonnet-test',spawn:fakeClaudeSpawn({stdout:developerResult,onStdin:value=>{if(value)prompts.push(value)}})});await adapter.execute({...claudeContext,task:{...claudeContext.task,description:'Acceptance criteria:\n- Critério real\n- Outro critério'},stageContext:{prompt:'Existing stage context'} as any});const explicit=prompts.find(prompt=>prompt.includes('ACCEPTANCE CRITERIA'))||'';assert.match(explicit,/ACCEPTANCE CRITERIA/);assert.match(explicit,/\[AC1\] Critério real/);assert.match(explicit,/\[AC2\] Outro critério/);assert.match(explicit,/dialog/);assert.match(explicit,/messageIncludes/);assert.match(explicit,/separate dialog click/);prompts.length=0;await adapter.execute({...claudeContext,task:{...claudeContext.task,description:'Sem critérios explícitos'}});const fallback=prompts.find(prompt=>prompt.includes('ACCEPTANCE CRITERIA'))||'';assert.match(fallback,/ACCEPTANCE CRITERIA/);assert.match(fallback,/None explicitly defined\./);});
