import {LocalWorkspaceTransport,calculateWorkspaceChangeSet} from '@orchestrator/workspace';
function fixtureGit(){const dir=mkdtempSync(join(tmpdir(),'orchestrator-workspace-'));execFileSync('git',['init','-q'],{cwd:dir});execFileSync('git',['config','user.email','test@example.com'],{cwd:dir});execFileSync('git',['config','user.name','Test'],{cwd:dir});writeFileSync(join(dir,'tracked.txt'),'before\n');execFileSync('git',['add','tracked.txt'],{cwd:dir});execFileSync('git',['commit','-qm','fixture'],{cwd:dir});return dir;}
test('workspace baseline is empty for a clean Git fixture',async()=>{const transport=new LocalWorkspaceTransport(fixtureGit());const baseline=await transport.captureBaseline();assert.equal(baseline.gitAvailable,true);assert.equal(baseline.statusBefore,'');assert.deepEqual(baseline.untrackedBefore,[]);});
test('workspace changeset includes a dirty file modified again during the task',async()=>{const dir=fixtureGit();writeFileSync(join(dir,'tracked.txt'),'preexisting\n');const transport=new LocalWorkspaceTransport(dir);const baseline=await transport.captureBaseline();writeFileSync(join(dir,'tracked.txt'),'developer\n');const after=await transport.captureState();const changes=calculateWorkspaceChangeSet(baseline,after);assert.equal(changes.preExistingChanges,true);assert.deepEqual(changes.filesChanged,['tracked.txt']);assert.deepEqual(changes.modified,['tracked.txt']);});
test('workspace changeset excludes an untouched pre-existing dirty file',async()=>{const dir=fixtureGit();writeFileSync(join(dir,'tracked.txt'),'preexisting\n');const transport=new LocalWorkspaceTransport(dir);const baseline=await transport.captureBaseline();const after=await transport.captureState();const changes=calculateWorkspaceChangeSet(baseline,after);assert.equal(changes.preExistingChanges,true);assert.deepEqual(changes.filesChanged,[]);assert.deepEqual(changes.preExistingFiles,['tracked.txt']);});
test('workspace changeset excludes pre-existing files and detects developer additions',async()=>{const dir=fixtureGit();writeFileSync(join(dir,'tracked.txt'),'preexisting\n');const transport=new LocalWorkspaceTransport(dir);const baseline=await transport.captureBaseline();writeFileSync(join(dir,'tracked.txt'),'developer\n');writeFileSync(join(dir,'new.txt'),'created\n');const after=await transport.captureState();const changes=calculateWorkspaceChangeSet(baseline,after);assert.equal(changes.preExistingChanges,true);assert.deepEqual(changes.filesChanged,['tracked.txt','new.txt']);assert.deepEqual(changes.added,['new.txt']);assert.deepEqual(changes.modified,['tracked.txt']);});
test('workspace changeset detects a developer deletion from a clean baseline',async()=>{const dir=fixtureGit();const transport=new LocalWorkspaceTransport(dir);const baseline=await transport.captureBaseline();unlinkSync(join(dir,'tracked.txt'));const after=await transport.captureState();const changes=calculateWorkspaceChangeSet(baseline,after);assert.deepEqual(changes.deleted,['tracked.txt']);assert.deepEqual(changes.filesChanged,['tracked.txt']);});
test('workspace without Git continues with gitAvailable false',async()=>{const dir=mkdtempSync(join(tmpdir(),'orchestrator-nogit-'));mkdirSync(join(dir,'nested'));const transport=new LocalWorkspaceTransport(dir);const baseline=await transport.captureBaseline();const after=await transport.captureState();assert.equal(baseline.gitAvailable,false);assert.equal(after.gitAvailable,false);assert.deepEqual(calculateWorkspaceChangeSet(baseline,after).filesChanged,[]);});
test('workspace transport exposes only read-only Git inspection commands',async()=>{const transport=new LocalWorkspaceTransport(fixtureGit());assert.equal(await transport.gitStatus(),'');assert.equal(await transport.gitDiff(),'');await assert.rejects(transport.checkout('main'),/read-only/);});

test('cli invocation errors are not retried by the pipeline',async()=>{let calls=0;const adapter:any={execute:async()=>{calls++;throw Object.assign(new Error('wrapper invocation failed'),{kind:'cli_invocation_error'});}};const runner=new PipelineRunner(adapter,{onStageStart(){},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){}});await assert.rejects(runner.run({task:{} as any,workspaceContext:{} as any,projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}},['developer']),/wrapper invocation failed/);assert.equal(calls,1);});
test('Windows cmd invocation treats executable separately from complex args',()=>{for(const executable of ['C:\\tools\\claude.cmd','C:\\Program Files\\Claude\\claude.cmd','C:\\Users\\aghiggi\\AppData\\Roaming\\npm\\claude.cmd']){const invocation=buildWindowsCmdInvocation({executable,args:['-p','--model','sonnet','Bash(git status:*)','Bash(php -l:*)','Bash(npm run test:*)','& | > < ^ ( ) * :','C:\\Program Files\\workspace']});const commandLine=invocation.args[2],unescaped=commandLine.replace(/\^/g,'');assert.equal(invocation.command,'cmd.exe');assert.equal(invocation.shell,false);assert.ok(!commandLine.includes('\\"'));assert.ok(unescaped.includes(executable));assert.ok(unescaped.includes('Bash(php -l:*)'));assert.ok(unescaped.includes('Bash(npm run test:*)'));}});
test('Claude Code Prompt Refiner uses haiku independently and sends request through stdin without tools',async()=>{let stdin='';let observedArgs:string[]=[];const refiner=new ClaudeCodePromptRefiner('haiku',{timeoutMs:1000,env:{CLAUDE_CLI_PATH:'claude'},spawn:(command,args,options)=>{observedArgs=args;return fakeClaudeSpawn({stdout:JSON.stringify({result:JSON.stringify({title:'Refined',objective:'Implement request',acceptanceCriteria:['done']})}),onStdin:value=>{stdin=value}})(command,args,options);}});const result=await refiner.refine({request:'special & request',workspaceName:'demo',workspaceBranch:'main'});assert.equal(result.title,'Refined');assert.ok(observedArgs.includes('-p'));assert.ok(observedArgs.includes('--model'));assert.ok(observedArgs.includes('haiku'));assert.ok(!observedArgs.includes('--allowedTools'));assert.ok(!observedArgs.includes('--disallowedTools'));assert.ok(stdin.includes('task specification refiner'));assert.ok(stdin.includes('special & request'));assert.equal(stdin.includes('sonnet'),false);});
test('Claude 2.1.287 capabilities parse help from stdout, stderr and aliases',()=>{const fixture='Claude Code - starts an interactive session by default, use -p/--print for non-interactive output\n--allowedTools, --allowed-tools <tools...>\n--disallowedTools, --disallowed-tools <tools...>\n--model <model>\n--output-format <format>\n--permission-mode <mode>\n--permission-prompts <target>\n--tools <tools...>\nacceptEdits auto bypassPermissions manual dontAsk plan';const stdout=parseClaudeCapabilities(fixture);const stderr=parseClaudeCapabilities(fixture);assert.deepEqual(stdout,stderr);assert.ok(stdout.supportedFlags.includes('-p'));assert.ok(stdout.supportedFlags.includes('--print'));assert.ok(stdout.supportedFlags.includes('--allowed-tools'));assert.ok(stdout.supportedFlags.includes('--disallowed-tools'));assert.ok(stdout.supportedFlags.includes('--permission-prompts'));assert.ok(!stdout.supportedFlags.includes('--max-turns'));const args=buildClaudeArgs({model:'sonnet',supportedFlags:stdout.supportedFlags,allowedTools:['Read','Bash(php -l:*)'],disallowedTools:['Bash(git commit:*)'],permissionMode:'dontAsk',maxTurns:15,safeArgs:[],outputFormat:'json'});assert.deepEqual(args.slice(-7),['--allowedTools','Read,Bash(php -l:*)','--disallowedTools','Bash(git commit:*)','--permission-mode','dontAsk','--permission-prompts','none'].slice(-7));});
test('required BLOCKED tester stops without provider failure or fix cycle',async()=>{const roles:string[]=[];const adapter:any={execute:async(input:any)=>{roles.push(input.stage);return{output:'blocked',tokenUsage:0,structuredResult:input.stage==='tester'?{status:'BLOCKED',blockReason:'No safe test command was detected'}:{status:'COMPLETED'}};}};const runner=new PipelineRunner(adapter,{onStageStart(){},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){throw new Error('provider failure should not occur');}});const base:any={task:{id:'blocked-required',title:'Blocked',description:'task',configSnapshot:{autoFixEnabled:true,maxFixCycles:2,testerRequired:true}},workspaceContext:{id:'w',type:'local',location:process.cwd()},projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}};await assert.rejects(runner.run(base,['developer','tester','reviewer']),error=>{assert.equal((error as any).kind,'pipeline_incomplete');assert.equal((error as any).details.reason,'tester_blocked');return true;});assert.deepEqual(roles,['developer','tester']);});
