test('workspace token guard is optional, ordered after task budget and exposed in UI',()=>{const server=readFileSync(new URL('./server.ts',import.meta.url),'utf8');const main=readFileSync(new URL('../../web/src/main.tsx',import.meta.url),'utf8');const completedUsage=(rows:any[],limit:number,enforce:boolean)=>{const tokens=rows.filter(x=>x.status==='completed').reduce((sum,x)=>sum+Number(x.tokenUsage||0),0);return enforce&&limit>0&&tokens>=limit};assert.equal(completedUsage([{status:'completed',tokenUsage:100}],100,false),false);assert.equal(completedUsage([{status:'completed',tokenUsage:99}],100,true),false);assert.equal(completedUsage([{status:'completed',tokenUsage:100}],100,true),true);assert.equal(completedUsage([{status:'running',tokenUsage:100}],100,true),false);assert.match(server,/enforceTokenUsageLimit INTEGER NOT NULL DEFAULT 0/);assert.match(server,/enforceTokenUsageLimit/);assert.match(server,/e\.status='completed'/);assert.match(server,/assertWorkspaceTokenLimit\(workspace,task\.id,role\)/);assert.match(server,/workspace\.token_limit_exceeded/);assert.match(server,/workspaceTokenLimitExceeded/);assert.match(main,/Bloquear ao atingir/);assert.match(main,/Somente alerta/);assert.match(main,/Limite de tokens do workspace atingido/);assert.match(main,/Preservado · limite do workspace/);assert.match(main,/workspace\.token_limit_exceeded/);});
