test('Claude mission planner uses mocked CLI only and rejects invalid JSON without Mock fallback',async()=>{let calls=0;let stdin='';const planner=new ClaudeCodeMissionPlanner({model:'sonnet',executable:'claude',timeoutMs:1000,spawn:(_command:string,args:string[],_options:any)=>{calls++;const child:any=new EventEmitter();child.stdout=new EventEmitter();child.stderr=new EventEmitter();child.stdin={end(value?:string){stdin=value||'';const output=args.includes('--help')?'Claude Code -p, --print\n--model <model>\n--output-format <format>':JSON.stringify({summary:'ok',assumptions:[],risks:[],tasks:[{key:'T1',title:'A',description:'a',acceptanceCriteria:[],dependsOn:[]} ]});setImmediate(()=>{child.stdout.emit('data',Buffer.from(output));child.emit('close',0);});}};child.kill=()=>{};return child;}});const plan=await planner.plan({title:'Mission',request:'Request',workspace:{name:'Demo'},projectContext:{version:2,status:'ready',sourceCommitSha:'abc',context:{files:['README.md']}},projectRules:[]});assert.equal(plan.tasks[0].title,'A');assert.equal(calls,2);assert.match(stdin,/Project Context/);const invalid=new ClaudeCodeMissionPlanner({model:'sonnet',executable:'claude',spawn:(_command:string,args:string[])=>{const child:any=new EventEmitter();child.stdout=new EventEmitter();child.stderr=new EventEmitter();child.stdin={end(){setImmediate(()=>{child.stdout.emit('data',Buffer.from(args.includes('--help')?'Claude Code -p, --print':'not json'));child.emit('close',0);});}};child.kill=()=>{};return child;}});await assert.rejects(invalid.plan({title:'M',request:'R',workspace:{}}),error=>{assert.equal((error as any).kind,'validation_error');return true;});});
