test('mission runner hardening keeps dependency order, snapshots and managed environments safe',()=>{const server=readFileSync(new URL('./server.ts',import.meta.url),'utf8');const tasks=[{id:'A',dependsOn:[],status:'approved',taskId:'ta'},{id:'B',dependsOn:['A'],status:'approved',taskId:'tb'},{id:'C',dependsOn:['B'],status:'approved',taskId:'tc'}];const ready=(current:any)=>tasks.filter(task=>current.dependsOn.includes(task.id));assert.equal(ready(tasks[0]).length,0);assert.equal(ready(tasks[1])[0].id,'A');assert.equal(ready(tasks[2])[0].id,'B');assert.match(server,/const dependencyIds=current\.dependsOn\|\|\[\]/);assert.match(server,/await runTask\(task\)/);assert.match(server,/mission_planner_configs/);assert.match(server,/mission_managed_environment/);assert.match(server,/runningMissions/);const snapshot=createTaskConfigSnapshot(['planner','developer','tester','reviewer'],{persistedAgentConfigs:{planner:{provider:'mock',model:'mock-fast'},developer:{provider:'mock',model:'mock-fast'},tester:{provider:'mock',model:'mock-fast'},reviewer:{provider:'mock',model:'mock-fast'}},executionPolicy:{autoFixEnabled:true,maxFixCycles:2,testerRequired:false}},DEFAULT_POLICY,DEFAULT_GATES);assert.equal(snapshot.agentConfigs.length,4);});
